#include <iostream>

void down(int n) {
    if (n == 0) {
        return;
    }
    std::cout << "往下 " << n << std::endl;
    down(n - 1);
    std::cout << "回来 " << n << std::endl;
}

int main() {
    down(2);
    return 0;
}

#include <iostream>

void show(int n) {
    if (n == 0) {
        std::cout << "到站" << std::endl;
        return;
    }
    show(n - 1);
    std::cout << n << std::endl;
}

int main() {
    show(3);
    return 0;
}
